namespace sv_60221d3b0df04f0994233699693664aa.Services;

public class WarehouseInfo
{
    public string Id { get; set; } = "warehouse-a";
    public string Name { get; set; } = "Warehouse A";
}

/// <summary>
/// Scoped service holding the current warehouse selection for a single user circuit.
/// All interactive components in the same circuit share this instance.
/// </summary>
public class WarehouseState
{
    public static readonly IReadOnlyList<WarehouseInfo> AvailableWarehouses =
    [
        new() { Id = "warehouse-a", Name = "Warehouse A" },
        new() { Id = "warehouse-b", Name = "Warehouse B" },
        new() { Id = "warehouse-c", Name = "Warehouse C" },
    ];

    private WarehouseInfo _current = AvailableWarehouses[0];

    public WarehouseInfo Current => _current;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        var warehouse = AvailableWarehouses.FirstOrDefault(w => w.Id == warehouseId);
        if (warehouse is not null && warehouse.Id != _current.Id)
        {
            _current = warehouse;
            OnChange?.Invoke();
        }
    }
}

namespace sv_60221d3b0df04f0994233699693664aa.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribers.
/// Each user circuit gets its own instance, ensuring independent state per user.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentAlertCount { get; private set; }

    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Start polling. Uses reference counting so multiple components can subscribe
    /// without creating duplicate timers.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Stop polling when a subscriber leaves. Only stops the timer when
    /// all subscribers have unsubscribed.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();
            _timer = null;
            _cts?.Dispose();
            _cts = null;
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                await RefreshAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task RefreshAsync()
    {
        CurrentAlertCount = await GetLowStockCountAsync(_warehouseState.Current.Id);
        OnAlertCountChanged?.Invoke();
    }

    private async void OnWarehouseChanged()
    {
        // When warehouse changes, immediately refresh the alert count
        await RefreshAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

