@page "/dashboard"
@rendermode InteractiveServer
@inject sv_60221d3b0df04f0994233699693664aa.Services.WarehouseState WarehouseState
@inject sv_60221d3b0df04f0994233699693664aa.Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@WarehouseState.Current.Name</p>
                <p class="text-muted">ID: @WarehouseState.Current.Id</p>
            </div>
        </div>
    </div>

    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text">
                    @if (AlertService.CurrentAlertCount > 0)
                    {
                        <span class="fs-2 text-danger fw-bold">@AlertService.CurrentAlertCount</span>
                        <span class="text-muted ms-2">items below minimum levels</span>
                    }
                    else
                    {
                        <span class="fs-2 text-success fw-bold">0</span>
                        <span class="text-muted ms-2">all stock levels OK</span>
                    }
                </p>
                <p class="text-muted"><small>Refreshes every 10 seconds</small></p>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnAlertCountChanged += _alertHandler;

        // Start polling when dashboard is visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;

        // Stop polling when user leaves the page
        AlertService.StopPolling();
    }
}

